#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_quality;
uniform float amzp_detail;
uniform float amzp_split;
uniform float amzp_showGrid;
uniform float amzp_alpha;




    const float PI = 3.141592653589793;

    float3 rgb2ybr(float3 rgb){

      float3 ybr = float3(0.299,0.587,0.114) * rgb.r +
                 float3(0.0,0.0,0.0);
      float y = dot(rgb, float3(0.299,0.587,0.114));
      float cb = (rgb.b - y) * 0.564 + 0.5;
      float cr = (rgb.r - y) * 0.713 + 0.5;
      return float3(y, cb, cr);
    }
    float3 ybr2rgb(float3 ybr){
      float y=ybr.x, cb=ybr.y-0.5, cr=ybr.z-0.5;
      float r = y + 1.403*cr;
      float b = y + 1.773*cb;
      float g = (y - 0.299*r - 0.114*b) / max(0.587, 1e-6);
      return clamp(float3(r,g,b), 0.0, 1.0);
    }

    float aScale(float k){ return (k==0.0)? 1.0/sqrt(2.0) : 1.0; }


    float qLuma(int u, int v){

      int idx = v*8 + u;
      int qv[64];

      qv[0]=16; qv[1]=11; qv[2]=10; qv[3]=16; qv[4]=24; qv[5]=40; qv[6]=51; qv[7]=61;
      qv[8]=12; qv[9]=12; qv[10]=14; qv[11]=19; qv[12]=26; qv[13]=58; qv[14]=60; qv[15]=55;
      qv[16]=14; qv[17]=13; qv[18]=16; qv[19]=24; qv[20]=40; qv[21]=57; qv[22]=69; qv[23]=56;
      qv[24]=14; qv[25]=17; qv[26]=22; qv[27]=29; qv[28]=51; qv[29]=87; qv[30]=80; qv[31]=62;
      qv[32]=18; qv[33]=22; qv[34]=37; qv[35]=56; qv[36]=68; qv[37]=109; qv[38]=103; qv[39]=77;
      qv[40]=24; qv[41]=35; qv[42]=55; qv[43]=64; qv[44]=81; qv[45]=104; qv[46]=113; qv[47]=92;
      qv[48]=49; qv[49]=64; qv[50]=78; qv[51]=87; qv[52]=103; qv[53]=121; qv[54]=120; qv[55]=101;
      qv[56]=72; qv[57]=92; qv[58]=95; qv[59]=98; qv[60]=112; qv[61]=100; qv[62]=103; qv[63]=99;
      return float(qv[idx]);
    }


    bool keepCoeff(int u, int v, int mode){
      if(mode==0){ 
        return (u==0 && v==0) || (u==1 && v==0) || (u==0 && v==1);
      } else if(mode==1){ 
        if((u==0 && v==0)||(u==1&&v==0)||(u==0&&v==1)||(u==1&&v==1)||(u==2&&v==0)||(u==0&&v==2)) return true;
        return false;
      } else { 
        int sum = u+v;
        return (sum<=3) || (u==3&&v==0) || (u==0&&v==3);
      }
    }

    void amzRender(){
      float2 uv = amzScreenNorm();
      float2 texel = float2(1.0) / max(screen.zw, float2(1.0));


      float splitPx = amzp_split * screen.zw.x;
      float xPx = uv.x * screen.zw.x;
      float3 srcRGB = amzTexture(0, uv).rgb;

      if(xPx < splitPx){

        amzOutput = float4(srcRGB, 1.0) * amzp_alpha;
        return;
      }


      float2 pPx = floor(uv * screen.zw);
      float2 blockBase = floor(pPx / 8.0) * 8.0;
      float2 xy = pPx - blockBase; 


      float3 S[64];
      int k=0;
      for(int j=0;j<8;j++){
        for(int i=0;i<8;i++){
          float2 sp = (blockBase + float2(float(i), float(j)) + 0.5) * texel;
          float3 ybr = rgb2ybr(amzTexture(0, sp).rgb);
          S[k] = (ybr - float3(0.0,0.5,0.5)) * 256.0; 
          k++;
        }
      }

      int mode = int(amzp_detail); 
      float qScale = amzp_quality; 


      float3 recon = float3(0.0);
      for(int v=0; v<8; v++){
        for(int u=0; u<8; u++){
          if(!keepCoeff(u,v,mode)) continue;

          float3 F = float3(0.0);
          int idx=0;
          for(int yb=0; yb<8; yb++){
            for(int xb=0; xb<8; xb++){
              float cx = cos(( (2.0*float(xb)+1.0)*float(u)*PI )/16.0);
              float cy = cos(( (2.0*float(yb)+1.0)*float(v)*PI )/16.0);
              F += S[idx] * (cx*cy);
              idx++;
            }
          }
          F *= 0.25 * aScale(float(u)) * aScale(float(v));

          float qv = qLuma(u,v) * qScale;
          F = floor(F / qv + 0.5) * qv;


          float cxp = cos(( (2.0*xy.x+1.0)*float(u)*PI )/16.0);
          float cyp = cos(( (2.0*xy.y+1.0)*float(v)*PI )/16.0);
          recon += F * (cxp*cyp) * 0.25 * aScale(float(u)) * aScale(float(v));
        }
      }


      float3 ybrRec = recon / 256.0 + float3(0.0,0.5,0.5);
      float3 rgbRec = ybr2rgb(ybrRec);


      if((amzp_showGrid>0.5)){
        float2 g = fract(pPx/8.0);
        float edge = step(g.x,0.02)+step(0.98,g.x)+step(g.y,0.02)+step(0.98,g.y);
        rgbRec = mix(rgbRec, float3(0.0), clamp(edge,0.0,1.0));
      }

      amzOutput = float4(rgbRec, 1.0) * amzp_alpha;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

